use std::{fmt::Debug, io};

use log::{debug, error, trace, warn};
use netlink_packet_core::{
    Emitable, EncodeError, NetlinkDeserializable, NetlinkMessage,
    NetlinkMessagePayload,
};
use netlink_proto::NetlinkMessageCodec;

/// audit specific implementation of [`NetlinkMessageCodec`] due to the
/// protocol violations in messages generated by kernal audit.
///
/// Among the known bugs in kernel audit messages:
/// - `nlmsg_len` sometimes contains the padding too (it shouldn't)
/// - `nlmsg_len` sometimes doesn't contain the header (it really should)
///
/// See also:
/// - https://blog.des.no/2020/08/netlink-auditing-and-counting-bytes/
/// - https://github.com/torvalds/linux/blob/b5013d084e03e82ceeab4db8ae8ceeaebe76b0eb/kernel/audit.c#L2386
/// - https://github.com/mozilla/libaudit-go/issues/24
/// - https://github.com/linux-audit/audit-userspace/issues/78
#[non_exhaustive]
pub struct NetlinkAuditCodec {
    // we don't need an instance of this, just the type
    _private: (),
}

impl NetlinkMessageCodec for NetlinkAuditCodec {
    fn decode<T>(
        src: &mut [u8],
    ) -> io::Result<Option<(NetlinkMessage<T>, usize)>>
    where
        T: NetlinkDeserializable + Debug,
    {
        debug!("NetlinkAuditCodec: decoding next message");

        let mut offset = 0;
        loop {
            let remaining = &mut src[offset..];

            // If there's nothing to read, return Ok(None)
            if remaining.is_empty() {
                trace!("buffer is empty");
                return Ok(None);
            }

            if remaining.len() < 4 {
                error!(
                    "failed to decode datagram, discarding buffer: {:x?}.",
                    remaining
                );
                return Ok(None);
            }

            let mut header = [0u8; 4];
            header.copy_from_slice(&remaining[..4]);
            let declared_len = u32::from_ne_bytes(header) as usize;
            let remaining_len = remaining.len();

            let len = if (remaining_len as isize - declared_len as isize) <= 16
            {
                // The audit messages are sometimes truncated, because the
                // length specified in the header does not take the header
                // itself into account. To workaround this, we use the whole
                // datagram as the message. We've noticed two occurences of
                // truncated packets:
                //
                // - the length of the header is not included (see also: https://github.com/mozilla/libaudit-go/issues/24)
                // - some rule message have some padding for alignment (see https://github.com/linux-audit/audit-userspace/issues/78)
                //   which is not taken into account in the buffer length.
                //
                // How do we know that's the right length? Due to an
                // implementation detail and to the fact that netlink is a
                // datagram protocol.
                //
                // - netlink datagrams hold a single audit message, so the extra
                //   bytes cannot belong to another message.
                if declared_len != remaining_len {
                    warn!("found what looks like a truncated audit packet");
                    warn!(
                        "using datagram length {} instead of {}",
                        remaining_len, declared_len
                    );
                }
                remaining_len
            } else {
                declared_len
            };

            if len == 0 {
                error!(
                    "failed to decode datagram, discarding buffer: {:x?}.",
                    remaining
                );
                return Ok(None);
            }

            let corrected;
            let bytes: &[u8] = if declared_len != len {
                let mut buf = remaining[..len].to_vec();
                buf[..4].copy_from_slice(&(len as u32).to_ne_bytes());
                corrected = buf;
                &corrected
            } else {
                &remaining[..len]
            };

            match NetlinkMessage::<T>::deserialize(bytes) {
                Ok(packet) => {
                    trace!("<<< {:?}", packet);
                    return Ok(Some((packet, offset + len)));
                }
                Err(e) => {
                    error!("failed to decode packet {:#x?}: {}", bytes, e);
                    offset += len;
                    // continue looping, there may be more messages in the
                    // datagram
                }
            }
        }
    }

    fn encode<T>(
        msg: NetlinkMessage<T>,
        buf: &mut Vec<u8>,
    ) -> Result<(), EncodeError>
    where
        T: NetlinkMessagePayload + Debug,
    {
        msg.emit(buf)?;
        trace!(">>> {:?}", msg);
        Ok(())
    }
}
